'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'
import { isAdmin } from '@/utils/admin'

export async function deleteQuestion(id: string) {
    const isUserAdmin = await isAdmin()
    if (!isUserAdmin) {
        return { success: false, message: 'Unauthorized' }
    }

    const supabase = await createClient()
    const { error } = await supabase
        .from('questions')
        .delete()
        .eq('id', id)

    if (error) {
        return { success: false, message: error.message }
    }

    revalidatePath('/dashboard/admin')
    return { success: true, message: 'Soal berhasil dihapus' }
}

export async function createQuestion(formData: FormData) {
    const isUserAdmin = await isAdmin()
    if (!isUserAdmin) {
        return { success: false, message: 'Unauthorized' }
    }

    const type = formData.get('type') as any // TWK, TIU, TKP
    const content = formData.get('content') as string
    const category = formData.get('category') as string // Sub-category
    const explanation = formData.get('explanation') as string
    const correctAnswer = formData.get('correct_answer') as string // A, B, C...

    const supabase = await createClient()

    // 1. Insert Question
    const { data: question, error: qError } = await supabase
        .from('questions')
        .insert({
            type,
            content,
            category,
            explanation
        })
        .select()
        .single()

    if (qError) return { success: false, message: qError.message }

    // 2. Prepare Options
    const optionLabels = ['A', 'B', 'C', 'D', 'E']
    const optionsToInsert = optionLabels.map(label => {
        const score = formData.get(`score_${label.toLowerCase()}`)
        return {
            question_id: question.id,
            content: formData.get(`option_${label.toLowerCase()}`) as string,
            is_correct: label === correctAnswer,
            score_value: type === 'TKP' ? parseInt(score as string || '0') : (label === correctAnswer ? 1 : 0)
        }
    })

    // 3. Insert Options
    const { error: oError } = await supabase
        .from('options')
        .insert(optionsToInsert)

    if (oError) {
        // Cleanup question if options fail?
        await supabase.from('questions').delete().eq('id', question.id)
        return { success: false, message: oError.message }
    }

    revalidatePath('/dashboard/admin')
    return { success: true, message: 'Soal baru berhasil dibuat' }
}

export async function updateQuestion(id: string, formData: FormData) {
    const isUserAdmin = await isAdmin()
    if (!isUserAdmin) {
        return { success: false, message: 'Unauthorized' }
    }

    const type = formData.get('type') as any
    const content = formData.get('content') as string
    const category = formData.get('category') as string
    const explanation = formData.get('explanation') as string
    const correctAnswer = formData.get('correct_answer') as string

    const supabase = await createClient()

    // 1. Update Question
    const { error: qError } = await supabase
        .from('questions')
        .update({
            type,
            content,
            category,
            explanation
        })
        .eq('id', id)

    if (qError) return { success: false, message: qError.message }

    // 2. Clear Existing Options
    const { error: dError } = await supabase
        .from('options')
        .delete()
        .eq('question_id', id)

    if (dError) return { success: false, message: dError.message }

    // 3. Insert New Options
    const optionLabels = ['A', 'B', 'C', 'D', 'E']
    const optionsToInsert = optionLabels.map(label => {
        const score = formData.get(`score_${label.toLowerCase()}`)
        return {
            question_id: id,
            content: formData.get(`option_${label.toLowerCase()}`) as string,
            is_correct: label === correctAnswer,
            score_value: type === 'TKP' ? parseInt(score as string || '0') : (label === correctAnswer ? 1 : 0)
        }
    })

    const { error: oError } = await supabase
        .from('options')
        .insert(optionsToInsert)

    if (oError) return { success: false, message: oError.message }

    revalidatePath('/dashboard/admin')
    return { success: true, message: 'Soal berhasil diupdate' }
}

'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'

export async function updateProfile(formData: FormData) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        throw new Error("Unauthorized")
    }

    // Extract Data
    const avatarUrl = formData.get('avatarUrl') as string

    const updates: Record<string, string | undefined> = {
        updated_at: new Date().toISOString(),
        full_name: formData.get('fullName') as string,
    }

    if (avatarUrl) {
        updates.avatar_url = avatarUrl
    }

    const { error } = await supabase
        .from('profiles')
        .update(updates)
        .eq('id', user.id)

    if (error) {
        console.error('Update profile error', error)
        return { error: error.message }
    }

    revalidatePath('/dashboard', 'layout')
    return { success: true }
}

export async function updateProfileInfo(data: {
    full_name?: string;
    bio?: string;
    avatar_url?: string;
    phone_number?: string;
    birth_date?: string;
    gender?: string;
    education_level?: string;
    target_instance?: string;
}) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        return { success: false, error: 'Not authenticated' }
    }

    const updates: Record<string, string | null | undefined> = {
        updated_at: new Date().toISOString()
    }

    if (data.full_name !== undefined) updates.full_name = data.full_name
    if (data.bio !== undefined) updates.bio = data.bio
    if (data.avatar_url !== undefined) updates.avatar_url = data.avatar_url
    if (data.phone_number !== undefined) updates.phone_number = data.phone_number || null
    if (data.birth_date !== undefined) updates.birth_date = data.birth_date || null
    if (data.gender !== undefined) updates.gender = data.gender || null
    if (data.education_level !== undefined) updates.education_level = data.education_level || null
    if (data.target_instance !== undefined) updates.target_instance = data.target_instance || null

    const { error } = await supabase
        .from('profiles')
        .update(updates)
        .eq('id', user.id)

    if (error) {
        console.error('Update profile error', error)
        return { success: false, error: error.message }
    }

    revalidatePath('/', 'layout')
    revalidatePath('/dashboard', 'layout')
    revalidatePath('/dashboard/profile')
    return { success: true }
}

export async function updatePassword(data: { newPassword: string }) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        return { success: false, error: 'Not authenticated' }
    }

    const { error } = await supabase.auth.updateUser({
        password: data.newPassword
    })

    if (error) {
        console.error('Update password error', error)
        return { success: false, error: error.message }
    }

    return { success: true }
}

export async function deleteAccount() {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        return { success: false, error: 'Not authenticated' }
    }

    try {
        const { createClient: createAdminClient } = await import('@supabase/supabase-js')
        const adminClient = createAdminClient(
            process.env.NEXT_PUBLIC_SUPABASE_URL!,
            process.env.SUPABASE_SERVICE_ROLE_KEY!,
            {
                auth: {
                    autoRefreshToken: false,
                    persistSession: false
                }
            }
        )

        const { error: deleteError } = await adminClient.auth.admin.deleteUser(user.id)
        if (deleteError) throw deleteError
        await supabase.auth.signOut()
        return { success: true }
    } catch (error: any) {
        console.error('Delete account error:', error)
        return { success: false, error: error.message }
    }
}

import { createClient } from '@/utils/supabase/server'
import { Plus, FileText } from 'lucide-react'
import Link from 'next/link'
import QuestionCard from '@/components/admin/QuestionCard'
import AdminSearch from '@/components/admin/AdminSearch'

export const dynamic = 'force-dynamic'

export default async function AdminDashboard({
    searchParams,
}: {
    searchParams: Promise<{
        q?: string
        category?: string
    }>
}) {
    const supabase = await createClient()
    const params = await searchParams
    const query = params?.q || ''
    const category = params?.category || 'TWK'

    // Construct Query with JOIN to options
    let dbQuery = supabase
        .from('questions')
        .select('*, options(*)', { count: 'exact' })
        .order('created_at', { ascending: false })

    if (category) {
        // Here 'category' filter in UI corresponds to 'type' in DB
        dbQuery = dbQuery.eq('type', category)
    }

    if (query) {
        dbQuery = dbQuery.ilike('content', `%${query}%`)
    }

    const { data: questions, count } = await dbQuery.limit(100)

    return (
        <div className="space-y-8 pb-10">
            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-2xl border-2 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]">
                <div>
                    <h1 className="font-handwriting text-3xl font-bold text-gray-900 rotate-[-1deg] inline-block">
                        Bank Soal Manager
                    </h1>
                    <div className="flex items-center gap-3 mt-1">
                        <p className="text-gray-600 font-medium">
                            Kelola soal-soal latihan CPNS & Kedinasan.
                        </p>
                        <span className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded text-xs font-black border border-blue-200">
                            Total: {count || 0} Soal
                        </span>
                    </div>
                </div>
                <Link
                    href="/dashboard/admin/create"
                    className="flex items-center gap-2 bg-gray-900 text-white px-5 py-3 rounded-lg hover:bg-gray-800 transition font-bold shadow-lg transform hover:-translate-y-1 active:translate-y-0"
                >
                    <Plus size={20} /> Buat Soal Baru
                </Link>
            </div>

            {/* Filter / Search Bar */}
            <AdminSearch />

            {/* Question List Grid */}
            <div className="grid grid-cols-1 gap-4">
                {questions?.map((q) => (
                    <QuestionCard key={q.id} q={q as any} />
                ))}

                {(!questions || questions.length === 0) && (
                    <div className="text-center py-20 bg-white rounded-xl border-2 border-dashed border-gray-300">
                        <div className="bg-gray-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                            <FileText className="h-8 w-8 text-gray-400" />
                        </div>
                        <h3 className="text-lg font-bold text-gray-900">Tidak ada soal ditemukan</h3>
                        <p className="text-gray-500 mb-6">Coba ubah filter atau buat soal baru.</p>
                        <Link
                            href="/dashboard/admin/create"
                            className="inline-flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 font-bold transition"
                        >
                            <Plus size={18} /> Buat Soal Baru
                        </Link>
                    </div>
                )}
            </div>
        </div>
    )
}

'use client'

import React, { useState } from 'react'
import { Sparkles, Flame, Zap, Package, CreditCard, Smartphone, CheckCircle, ShieldCheck } from 'lucide-react'
import { toast } from 'sonner'
import PaperBackground from '@/components/PaperBackground'
import CheckDoodle from '@/components/CheckDoodle'
import { PRICING_PACKAGES } from '@/lib/constants'
import { createPackageTransaction, syncPaymentStatus } from '@/app/actions/payment'
import { cn } from '@/lib/utils'
import MockSnapModal from '@/components/dashboard/MockSnapModal'
import { X } from 'lucide-react'

export default function BeliPaketPage() {
    const [mockModalOpen, setMockModalOpen] = useState(false)
    const [currentTransaction, setCurrentTransaction] = useState<any>(null)

    const handleBuy = async (packageId: string) => {
        const loadingToast = toast.loading("Memproses pesanan...")

        try {
            const transaction = await createPackageTransaction(packageId)

            if (!transaction.token) {
                throw new Error("Gagal mendapatkan token pembayaran")
            }

            toast.dismiss(loadingToast)

            // CHECK IS MOCK?
            console.log("Transaction Token:", transaction.token)
            if (transaction.token.startsWith('mock_')) {
                setCurrentTransaction({
                    ...transaction,
                    amount: PRICING_PACKAGES.find(p => p.id === packageId)?.price || 0,
                    packageName: PRICING_PACKAGES.find(p => p.id === packageId)?.name || 'Paket'
                })
                setMockModalOpen(true)
                return
            }

            // REAL MIDTRANS FLOW
            // @ts-expect-error - snap is loaded via script
            window.snap.pay(transaction.token, {
                onSuccess: async function (result: any) {
                    const loadingId = toast.loading("Memverifikasi pembayaran...")
                    await syncPaymentStatus(transaction.orderId)
                    toast.success("Pembayaran Berhasil!", {
                        id: loadingId,
                        description: "Tiket tryout kamu akan segera ditambahkan."
                    })
                    console.log('success', result)
                },
                onPending: async function (result: any) {
                    const loadingId = toast.loading("Memperbarui status...")
                    await syncPaymentStatus(transaction.orderId)
                    toast.info("Pembayaran Tertunda", {
                        id: loadingId,
                        description: "Silakan selesaikan pembayaran sesuai instruksi."
                    })
                    console.log('pending', result)
                },
                onError: function (result: any) {
                    toast.error("Pembayaran Gagal")
                    console.log('error', result)
                },
                onClose: async function () {
                    const loadingId = toast.loading("Memperiksa status terakhir...")
                    await syncPaymentStatus(transaction.orderId)
                    toast.info("Pembayaran Ditutup", { id: loadingId })
                }
            })
        } catch (error: any) {
            toast.dismiss(loadingToast)
            toast.error("Terjadi Kesalahan", {
                description: error.message || "Gagal membuat transaksi."
            })
        }
    }

    // Helper to call our own webhook for simulation
    const simulateWebhook = async (status: string) => {
        if (!currentTransaction) return

        const loadingId = toast.loading("Simulasi verifikasi pembayaran...")
        setMockModalOpen(false)

        try {
            await fetch('/api/payments/webhook', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    order_id: currentTransaction.orderId,
                    transaction_status: status
                })
            })

            toast.dismiss(loadingId)

            if (status === 'settlement' || status === 'capture') {
                toast.success("Pembayaran (Simulasi) Berhasil!", {
                    description: "Quota tryout kamu sudah bertambah. Silakan refresh jika perlu."
                })
            } else if (status === 'pending') {
                toast.warning("Status: Pending", {
                    description: "Menunggu pembayaran..."
                })
            } else {
                toast.error("Status: Gagal/Expired")
            }
        } catch (e) {
            toast.dismiss(loadingId)
            toast.error("Gagal menghubungi server mock")
        }
    }

    return (
        <div className="font-body w-full flex flex-col relative">
            <PaperBackground />

            {/* MOCK MODAL */}
            <MockSnapModal
                isOpen={mockModalOpen}
                onClose={() => setMockModalOpen(false)}
                orderId={currentTransaction?.orderId || ''}
                amount={currentTransaction?.amount || 0}
                packageName={currentTransaction?.packageName || ''}
                onSuccess={() => simulateWebhook('settlement')}
                onPending={() => simulateWebhook('pending')}
                onError={() => simulateWebhook('expire')}
            />

            <div className="flex-1 flex flex-col justify-center items-center px-4 sm:px-6 py-6 sm:py-10 relative z-10 w-full max-w-7xl mx-auto">

                <div className="text-center mb-8 md:mb-16">
                    <h1 className="font-handwriting text-4xl sm:text-5xl md:text-6xl lg:text-7xl font-bold mb-4 text-gray-900 drop-shadow-sm flex items-center justify-center gap-4">
                        <Package className="w-12 h-12 text-indigo-600" /> Beli Paket
                    </h1>
                    <p className="font-handwriting text-xl sm:text-2xl md:text-3xl text-gray-600">Pilih "menu" latihanmu hari ini:</p>
                </div>

                <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 lg:gap-8 w-full max-w-6xl items-stretch">
                    {PRICING_PACKAGES.map((pkg) => (
                        <div
                            key={pkg.id}
                            className={cn(
                                "relative p-6 xl:p-8 border-2 transition-all duration-300 flex flex-col rounded-xl group",
                                pkg.bestSeller
                                    ? "bg-[#ffffeb] border-indigo-600 shadow-[10px_10px_0px_0px_rgba(79,70,229,0.15)] hover:shadow-[15px_15px_0px_0px_rgba(79,70,229,0.2)] lg:scale-[1.08] z-10"
                                    : "bg-white border-gray-300 shadow-[4px_4px_0px_0px_rgba(0,0,0,0.05)] hover:shadow-[10px_10px_0px_0px_rgba(0,0,0,0.1)]"
                            )}
                        >
                            {/* Tape decoration */}
                            <div className={cn(
                                "absolute -top-3 left-1/2 -translate-x-1/2 w-24 h-6 border-l border-r border-white/50 shadow-sm transition-transform",
                                pkg.bestSeller ? "bg-yellow-300 rotate-2 group-hover:rotate-0" : "bg-yellow-100/80 rotate-2 group-hover:rotate-0"
                            )}></div>

                            {pkg.bestSeller && (
                                <div className="absolute top-2 right-2 text-red-600 font-handwriting text-xs md:text-sm font-bold border-2 border-red-600 px-3 py-1 rounded rotate-[-12deg] bg-white animate-pulse flex items-center gap-1">
                                    BEST SELLER <Flame className="w-3 h-3 fill-red-600" />
                                </div>
                            )}

                            <h3 className="font-handwriting text-3xl font-bold text-gray-800 border-b-2 border-indigo-50 pb-2 mb-4">
                                {pkg.name}
                            </h3>

                            <div className="mb-2 font-handwriting">
                                <span className="text-4xl md:text-5xl font-bold text-indigo-600">Rp {(pkg.price / 1000).toLocaleString()}k</span>
                                <span className="text-gray-400 text-lg">/ {pkg.tokens} Token</span>
                            </div>

                            {pkg.savings > 0 && (
                                <p className="font-handwriting text-green-700 text-sm md:text-base mb-6 bg-green-100 inline-flex px-4 py-1.5 rounded-full items-center gap-2 w-fit shadow-sm">
                                    Hemat Rp {(pkg.savings / 1000).toLocaleString()}k! <Sparkles className="w-5 h-5" />
                                </p>
                            )}

                            <div className="space-y-4 mb-8 font-handwriting text-gray-700 flex-grow text-lg md:text-xl">
                                {pkg.features.map((feature, i) => (
                                    <div key={i} className="flex items-start gap-2.5">
                                        <CheckDoodle className="w-6 h-6 mt-1" />
                                        <span>{feature}</span>
                                    </div>
                                ))}
                            </div>

                            <button
                                onClick={() => handleBuy(pkg.id)}
                                className={cn(
                                    "w-full py-4 font-handwriting text-2xl font-bold rounded-lg transition-all cursor-pointer shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:shadow-none hover:translate-x-[2px] hover:translate-y-[2px]",
                                    pkg.bestSeller
                                        ? "bg-indigo-600 text-white border-2 border-gray-900"
                                        : "bg-indigo-50 text-indigo-600 border-2 border-indigo-200"
                                )}
                            >
                                {pkg.bestSeller ? `Ambil Paket ${pkg.name}` : `Pilih ${pkg.name}`}
                            </button>
                        </div>
                    ))}
                </div>

                {/* Best Practice Payment Instructions */}
                <div className="mt-16 sm:mt-24 w-full max-w-4xl mx-auto">
                    <div className="text-center mb-10">
                        <h2 className="font-handwriting text-3xl sm:text-4xl font-bold text-gray-900 flex items-center justify-center gap-3">
                            <ShieldCheck className="w-8 h-8 text-green-600" />
                            Cara Pembayaran Cepat & Aman
                        </h2>
                        <p className="font-handwriting text-xl text-gray-600 mt-2">Best practice supaya tryout-mu langsung aktif!</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 sm:gap-6 relative">
                        {/* Connecting Line for Desktop */}
                        <div className="hidden md:block absolute top-[45px] left-[10%] right-[10%] h-1 bg-gray-300 border-t-2 border-dashed border-gray-900 z-0 opacity-50"></div>

                        {/* Step 1 */}
                        <div className="relative z-10 flex flex-col items-center text-center group">
                            <div className="w-16 h-16 sm:w-20 sm:h-20 bg-[#ffffeb] border-2 border-gray-900 rounded-full flex items-center justify-center shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] group-hover:translate-x-[2px] group-hover:translate-y-[2px] group-hover:shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] transition-all mb-4 z-10">
                                <Package className="w-8 h-8 sm:w-10 sm:h-10 text-indigo-600" />
                            </div>
                            <div className="absolute top-0 right-[25%] bg-yellow-300 text-gray-900 font-black text-xs px-2 py-0.5 border-2 border-gray-900 rotate-12 z-20 shadow-sm">
                                1
                            </div>
                            <h3 className="font-handwriting text-xl font-bold text-gray-900 mb-2">Pilih Paket</h3>
                            <p className="font-handwriting text-lg text-gray-600">Tekan tombol pilih pada paket yang kamu inginkan.</p>
                        </div>

                        {/* Step 2 */}
                        <div className="relative z-10 flex flex-col items-center text-center group mt-6 md:mt-0">
                            <div className="w-16 h-16 sm:w-20 sm:h-20 bg-[#e0f2fe] border-2 border-gray-900 rounded-full flex items-center justify-center shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] group-hover:translate-x-[2px] group-hover:translate-y-[2px] group-hover:shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] transition-all mb-4 z-10">
                                <ShieldCheck className="w-8 h-8 sm:w-10 sm:h-10 text-blue-600" />
                            </div>
                            <div className="absolute top-0 right-[25%] bg-blue-300 text-gray-900 font-black text-xs px-2 py-0.5 border-2 border-gray-900 -rotate-12 z-20 shadow-sm">
                                2
                            </div>
                            <h3 className="font-handwriting text-xl font-bold text-gray-900 mb-2">Data Otomatis</h3>
                            <p className="font-handwriting text-lg text-gray-600">Sistem akan otomatis merekap nama dan email dari akunmu.</p>
                        </div>

                        {/* Step 3 */}
                        <div className="relative z-10 flex flex-col items-center text-center group mt-6 md:mt-0">
                            <div className="w-16 h-16 sm:w-20 sm:h-20 bg-[#fce7f3] border-2 border-gray-900 rounded-full flex items-center justify-center shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] group-hover:translate-x-[2px] group-hover:translate-y-[2px] group-hover:shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] transition-all mb-4 z-10">
                                <Smartphone className="w-8 h-8 sm:w-10 sm:h-10 text-pink-600" />
                            </div>
                            <div className="absolute top-0 right-[25%] bg-pink-300 text-gray-900 font-black text-xs px-2 py-0.5 border-2 border-gray-900 rotate-6 z-20 shadow-sm">
                                3
                            </div>
                            <h3 className="font-handwriting text-xl font-bold text-gray-900 mb-2">Pilih Metode</h3>
                            <p className="font-handwriting text-lg text-gray-600">Qris e-Wallet, Virtual Account (BCA, Mandiri, dll), Super Lengkap!</p>
                        </div>

                        {/* Step 4 */}
                        <div className="relative z-10 flex flex-col items-center text-center group mt-6 md:mt-0">
                            <div className="w-16 h-16 sm:w-20 sm:h-20 bg-[#dcfce7] border-2 border-gray-900 rounded-full flex items-center justify-center shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] group-hover:translate-x-[2px] group-hover:translate-y-[2px] group-hover:shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] transition-all mb-4 z-10">
                                <CheckCircle className="w-8 h-8 sm:w-10 sm:h-10 text-green-600" />
                            </div>
                            <div className="absolute top-0 right-[25%] bg-green-300 text-gray-900 font-black text-xs px-2 py-0.5 border-2 border-gray-900 -rotate-6 z-20 shadow-sm">
                                4
                            </div>
                            <h3 className="font-handwriting text-xl font-bold text-gray-900 mb-2">Lunas & Latihan</h3>
                            <p className="font-handwriting text-lg text-gray-600">Setelah dibayar, kuota otomatis masuk. Langsung Gas!</p>
                        </div>

                    </div>
                </div>

                <div className="mt-16 sm:mt-24 text-center w-full px-2 sm:px-0">
                    <div className="inline-block bg-[#fff740] p-6 md:p-8 shadow-md rotate-1 font-handwriting text-xl sm:text-2xl max-w-4xl relative rounded-xl border-2 border-gray-900 overflow-hidden">
                        <div className="absolute -top-2 left-1/2 -translate-x-1/2 w-4 h-4 rounded-full bg-red-500 shadow-sm z-10 border border-red-700"></div>
                        <p className="text-gray-900 leading-relaxed px-2 sm:px-4">
                            <strong>Catatan Admin:</strong> Masih ragu? Cicil aja pakai <strong>Paket Satuan</strong> dulu. Tapi kalau mau serius, <strong>Paket 5x</strong> paling untung! <Zap className="w-4 h-4 inline text-yellow-600" />
                        </p>
                        <div className="absolute bottom-1 right-2 opacity-20">
                            <Sparkles size={40} className="text-gray-900" />
                        </div>
                    </div>
                </div>

            </div>

        </div>
    )
}

import { createClient } from '@/utils/supabase/server'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import {
    CheckCircle2,
    XCircle,
    ArrowLeft,
    Trophy,
    Clock,
    Target,

    AlertTriangle,
    Sparkles,
    Flame,
    ClipboardList,
    Zap
} from 'lucide-react'
import ResultReviewClient from '@/components/practice/ResultReviewClient'
import RetakeButton from '@/components/practice/RetakeButton'
import ScrollToReviewButton from '@/components/practice/ScrollToReviewButton'
import ResultXPWrapper from '@/components/practice/ResultXPWrapper'
import PaperBackground from '@/components/PaperBackground'
import { getXPInfo } from '@/lib/dashboard'
import { cn, formatSubjectName } from '@/lib/utils'
import { PASSING_GRADES, SUBJECTS } from '@/lib/constants'

export default async function PracticeResultPage({ params }: { params: Promise<{ sessionId: string }> }) {
    const supabase = await createClient()
    const { sessionId } = await params

    // 1. Fetch Session Result
    const { data: session, error: sessionError } = await supabase
        .from('test_sessions')
        .select('*')
        .eq('id', sessionId)
        .single()

    if (sessionError || !session) {
        redirect('/dashboard/latihan')
    }

    if (session.status !== 'completed') {
        // Optional: redirect or show message
    }

    // Fetch user's total XP and metadata before this session (for popups)
    const [prevSessionsRes, profileRes] = await Promise.all([
        supabase
            .from('test_sessions')
            .select('total_score, end_time')
            .eq('user_id', session.user_id)
            .eq('status', 'completed')
            .neq('id', sessionId), // Exclude current session
        supabase
            .from('profiles')
            .select('streak_count, last_activity_date')
            .eq('id', session.user_id)
            .single()
    ])

    const allPreviousSessions = prevSessionsRes.data || []
    const profile = profileRes.data

    const previousTotalXP = allPreviousSessions.reduce((sum, s) => sum + (s.total_score || 0), 0) || 0
    const xpEarned = session.total_score || 0
    const xpInfo = getXPInfo(previousTotalXP, xpEarned)

    // Streak Logic: Show streak popup if this is the first session completed today
    const today = new Date().toISOString().split('T')[0]
    const otherSessionsToday = allPreviousSessions.filter(s =>
        s.end_time && new Date(s.end_time).toISOString().split('T')[0] === today
    )
    const isFirstSessionToday = otherSessionsToday.length === 0

    const enrichedXPInfo = {
        ...xpInfo,
        streakCount: profile?.streak_count || 0,
        isStreak: isFirstSessionToday
    }

    // 2. Fetch Detailed Answers
    const { data: rawAnswers, error: answersError } = await supabase
        .from('test_answers')
        .select(`
            id,
            question_id,
            option_id,
            questions (
                id,
                content,
                explanation,
                type,
                category,
                options (
                    id,
                    content,
                    is_correct,
                    score_value
                )
            ),
            selected_option: options (
                id,
                content,
                is_correct,
                score_value
            )
        `)
        .eq('session_id', sessionId)

    if (answersError) return <div>Error loading results</div>

    const answers = (rawAnswers || []).map((ans: any) => ({
        ...ans,
        selected_option: Array.isArray(ans.selected_option) ? ans.selected_option[0] || null : (ans.selected_option as any)
    }))

    // --- DATA PROCESSING ---

    // 1. Determine Module Type
    const uniqueTypes = Array.from(new Set(answers.map((a: any) => {
        const q = Array.isArray(a.questions) ? a.questions[0] : a.questions
        return q.type
    })))
    const isCombined = uniqueTypes.length > 1
    const singleType = isCombined ? null : uniqueTypes[0]

    // 2. Calculate Stats Helper
    const calculateStats = (filterType?: string) => {
        const filtered = filterType
            ? answers.filter((a: any) => (Array.isArray(a.questions) ? a.questions[0] : a.questions).type === filterType)
            : answers

        const total = filtered.length
        if (total === 0) return { total: 0, correct: 0, wrong: 0, empty: 0, score: 0, maxScore: 0, accuracy: 0 }

        let correct = 0
        let score = 0
        let maxScore = 0

        filtered.forEach((a: any) => {
            const q = Array.isArray(a.questions) ? a.questions[0] : a.questions
            const type = q.type
            const isCorrect = a.selected_option?.is_correct
            const val = a.selected_option?.score_value || 0

            if (type === 'TKP') {
                score += val
                maxScore += 5
                if (val >= 3) correct++
            } else {
                if (isCorrect) {
                    correct++
                    score += 5
                }
                maxScore += 5
            }
        })

        const wrong = total - correct // This is a simplified view for TKP
        const accuracy = Math.round((score / maxScore) * 100)

        // Correction for actual correct/wrong counts needed for display
        const realCorrect = filtered.filter((a: any) => {
            const q = Array.isArray(a.questions) ? a.questions[0] : a.questions
            if (q.type === 'TKP') return (a.selected_option?.score_value || 0) === 5
            return a.selected_option?.is_correct
        }).length

        const realWrong = filtered.length - realCorrect

        return { total, correct: realCorrect, wrong: realWrong, score, maxScore, accuracy }
    }

    const mainStats = calculateStats(singleType || undefined)

    // 3. Time Duration
    const startTime = new Date(session.start_time).getTime()
    const endTime = session.end_time ? new Date(session.end_time).getTime() : Date.now()
    const durationMinutes = Math.floor((endTime - startTime) / 60000)
    const durationSeconds = Math.floor(((endTime - startTime) % 60000) / 1000)

    // 4. Grade Calculation
    const getGrade = (percentage: number) => {
        if (percentage >= 80) return { label: 'A', color: 'text-green-500', bg: 'bg-green-500/10', border: 'border-green-500', text: 'Sangat Baik' }
        if (percentage >= 65) return { label: 'B', color: 'text-blue-500', bg: 'bg-blue-500/10', border: 'border-blue-500', text: 'Baik' }
        if (percentage >= 50) return { label: 'C', color: 'text-yellow-500', bg: 'bg-yellow-500/10', border: 'border-yellow-500', text: 'Cukup' }
        if (percentage >= 30) return { label: 'D', color: 'text-orange-500', bg: 'bg-orange-500/10', border: 'border-orange-500', text: 'Kurang' }
        return { label: 'E', color: 'text-red-500', bg: 'bg-red-500/10', border: 'border-red-500', text: 'Perlu Belajar Lagi' }
    }

    const grade = getGrade(mainStats.accuracy)

    // 5. Feedback Logic
    const getFeedback = () => {
        if (mainStats.accuracy >= 80) return <span>Luar biasa! Kamu sudah siap untuk menaklukkan soal-soal SKD sesungguhnya. Pertahankan! <Trophy className="inline-block w-5 h-5 text-yellow-500 align-text-bottom ml-1" /></span>
        if (mainStats.accuracy >= 60) return <span>Permulaan yang bagus. Ada beberapa materi yang perlu diperdalam lagi agar skor makin maksimal. <Zap className="inline-block w-5 h-5 text-blue-500 align-text-bottom ml-1" /></span>
        return <span>Jangan patah semangat! Perbanyak latihan soal dan pelajari pembahasan untuk meningkatkan pemahamanmu. <Flame className="inline-block w-5 h-5 text-orange-500 align-text-bottom ml-1" /></span>
    }

    // --- UI HELPERS ---

    const CategoryCard = ({ type, score, maxScore, total, correct }: { type: string; score: number; maxScore: number; total: number; correct: number }) => {
        const pct = Math.round((score / maxScore) * 100) || 0
        const typeUpper = type.toUpperCase() as keyof typeof PASSING_GRADES
        const passingGrade = PASSING_GRADES[typeUpper]
        const isPassed = score >= passingGrade
        const passColor = isPassed ? 'text-green-600' : 'text-red-500'

        return (
            <div className="bg-white border-2 border-gray-900 p-4 sm:p-5 rounded-2xl flex flex-col gap-3 relative overflow-hidden shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] group hover:scale-[1.02] transition-transform font-handwriting">
                <PaperBackground />
                <div className="flex justify-between items-center relative z-10">
                    <span className="text-sm font-bold text-gray-800 uppercase tracking-widest">{type}</span>
                    <span className={cn(
                        "text-[10px] px-2.5 py-1 rounded-full font-bold border-2 rotate-3",
                        isPassed ? "bg-green-100 text-green-700 border-green-300" : "bg-red-100 text-red-700 border-red-300"
                    )}>
                        {isPassed ? <span className="inline-flex items-center gap-1">LULUS <Sparkles className="w-3 h-3" /></span> : 'BELUM LULUS'}
                    </span>
                </div>
                <div className="mt-2 relative z-10">
                    <span className={cn("text-4xl font-black font-sans", passColor)}>{score}</span>
                    <span className="text-gray-400 text-lg font-sans"> / {maxScore}</span>
                </div>

                <div className="flex flex-col gap-1 text-xs font-bold text-gray-500 relative z-10 font-sans">
                    <div className="flex justify-between"><span>Passing Grade:</span> <span className="text-gray-900">{passingGrade}</span></div>
                    <div className="flex justify-between"><span>Benar:</span> <span className="text-gray-900">{correct}/{total} Soal</span></div>
                </div>

                {/* Mini Progress Bar */}
                <div className="w-full h-3 bg-gray-100 border-2 border-gray-900 rounded-full mt-2 overflow-hidden relative z-10">
                    <div
                        className={cn("h-full rounded-full border-r-2 border-gray-900 transition-all duration-1000", isPassed ? 'bg-green-500' : 'bg-red-500')}
                        style={{ width: `${Math.min(pct, 100)}%` }}
                    />
                </div>
            </div>
        )
    }

    return (
        <ResultXPWrapper xpInfo={enrichedXPInfo}>
            <div className="max-w-5xl mx-auto p-3 sm:p-8 space-y-6 sm:space-y-8 pb-32 font-handwriting">

                {/* 1. HERO SECTION */}
                <div className="relative overflow-hidden rounded-3xl bg-[#fff9c4] border-2 border-gray-900 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)]">
                    <PaperBackground />

                    <div className="relative p-6 sm:p-12 flex flex-col items-center text-center z-10">
                        <div className="mb-4">
                            <span className="px-4 py-1.5 rounded-full bg-gray-900 text-white text-sm font-bold uppercase tracking-widest rotate-2 inline-flex items-center gap-1">
                                HASIL {isCombined ? 'TRYOUT SKD' : `LATIHAN ${formatSubjectName(singleType || '')}`} <ClipboardList className="w-4 h-4" />
                            </span>
                        </div>

                        <h1 className="text-4xl md:text-5xl lg:text-6xl font-black mb-4 text-gray-900 drop-shadow-sm">
                            {grade.text}
                        </h1>
                        <p className="text-gray-700 text-lg md:text-xl max-w-2xl mx-auto mb-10 italic font-medium">
                            "{getFeedback()}"
                        </p>

                        <div className="flex flex-col md:flex-row items-center gap-10 md:gap-20 w-full justify-center">

                            {/* SCORE CIRCLE */}
                            <div className="relative group">
                                <div className={cn(
                                    "w-44 h-44 sm:w-56 sm:h-56 rounded-full border-4 border-gray-900 flex flex-col items-center justify-center bg-white shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] transition-transform hover:scale-105 relative",
                                    grade.border
                                )}>
                                    <div className="flex items-baseline gap-1">
                                        <span className={cn("text-7xl md:text-8xl font-black tracking-tighter leading-none font-sans", grade.color)}>
                                            {session.total_score}
                                        </span>
                                    </div>
                                    <span className="text-sm text-gray-500 font-bold mt-2 uppercase tracking-widest">Skor Akhir</span>

                                    {/* Doodle around score */}
                                    <div className="absolute -top-2 -right-2 opacity-20">
                                        <Sparkles size={40} className="text-gray-900" />
                                    </div>
                                </div>

                                {/* Grade Badge */}
                                <div className={cn(
                                    "absolute -right-4 -top-4 w-20 h-20 rounded-xl border-4 border-gray-900 flex items-center justify-center text-4xl font-black shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] rotate-12",
                                    grade.bg, grade.color
                                )}>
                                    {grade.label}
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-3 sm:gap-4 w-full md:w-auto">
                                <div className="bg-white p-3 sm:p-5 rounded-2xl border-2 border-gray-900 shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] flex flex-col items-start min-w-[140px] -rotate-1">
                                    <div className="flex items-center gap-2 text-gray-500 text-[10px] sm:text-sm font-bold uppercase mb-0.5 sm:mb-1">
                                        <Target size={14} className="text-blue-500 sm:w-4 sm:h-4" /> Akurasi
                                    </div>
                                    <span className="text-2xl sm:text-3xl font-black text-gray-900 font-sans">{mainStats.accuracy}%</span>
                                    <span className="text-[10px] sm:text-xs text-gray-400 font-medium whitespace-nowrap">Banyak Benernya</span>
                                </div>

                                <div className="bg-white p-3 sm:p-5 rounded-2xl border-2 border-gray-900 shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] flex flex-col items-start min-w-[140px] rotate-1">
                                    <div className="flex items-center gap-2 text-gray-500 text-[10px] sm:text-sm font-bold uppercase mb-0.5 sm:mb-1">
                                        <Clock size={14} className="text-orange-500 sm:w-4 sm:h-4" /> Waktu
                                    </div>
                                    <span className="text-2xl sm:text-3xl font-black text-gray-900 font-sans">{durationMinutes}<span className="text-base sm:text-lg">m</span> {durationSeconds}<span className="text-base sm:text-lg">d</span></span>
                                    <span className="text-[10px] sm:text-xs text-gray-400 font-medium whitespace-nowrap">Lama Mikirnya</span>
                                </div>

                                <div className="bg-white p-3 sm:p-5 rounded-2xl border-2 border-gray-900 shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] flex flex-col items-start min-w-[140px] rotate-1">
                                    <div className="flex items-center gap-2 text-green-600 text-[10px] sm:text-sm font-bold uppercase mb-0.5 sm:mb-1">
                                        <CheckCircle2 size={14} className="sm:w-4 sm:h-4" /> Benar
                                    </div>
                                    <span className="text-2xl sm:text-3xl font-black text-green-600 font-sans">{mainStats.correct}</span>
                                    <span className="text-[10px] sm:text-xs text-gray-400 font-medium whitespace-nowrap">Berhasil HJ</span>
                                </div>

                                <div className="bg-white p-3 sm:p-5 rounded-2xl border-2 border-gray-900 shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] flex flex-col items-start min-w-[140px] -rotate-1">
                                    <div className="flex items-center gap-2 text-red-500 text-[10px] sm:text-sm font-bold uppercase mb-0.5 sm:mb-1">
                                        <XCircle size={14} className="sm:w-4 sm:h-4" /> Salah
                                    </div>
                                    <span className="text-2xl sm:text-3xl font-black text-red-500 font-sans">{mainStats.wrong}</span>
                                    <span className="text-[10px] sm:text-xs text-gray-400 font-medium whitespace-nowrap">Zonk / Skip</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* 2. CATEGORY BREAKDOWN (If Combined) */}
                {isCombined && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <CategoryCard
                            type="TWK"
                            score={session.score_twk}
                            maxScore={calculateStats('TWK').maxScore}
                            total={calculateStats('TWK').total}
                            correct={calculateStats('TWK').correct}
                        />
                        <CategoryCard
                            type="TIU"
                            score={session.score_tiu}
                            maxScore={calculateStats('TIU').maxScore}
                            total={calculateStats('TIU').total}
                            correct={calculateStats('TIU').correct}
                        />
                        <CategoryCard
                            type="TKP"
                            score={session.score_tkp}
                            maxScore={calculateStats('TKP').maxScore}
                            total={calculateStats('TKP').total}
                            correct={calculateStats('TKP').correct} // Logic for TKP correct might need adjustment
                        />
                    </div>
                )}

                {/* 3. RECOMMENDATION CARD */}
                {/* Refined Logic: Handle multiple failures */}
                {isCombined && (
                    (() => {
                        // Calculate pass status for each section using centralized constants
                        const scores = [
                            { type: 'TWK', score: session.score_twk, target: PASSING_GRADES.TWK, passed: session.score_twk >= PASSING_GRADES.TWK },
                            { type: 'TIU', score: session.score_tiu, target: PASSING_GRADES.TIU, passed: session.score_tiu >= PASSING_GRADES.TIU },
                            { type: 'TKP', score: session.score_tkp, target: PASSING_GRADES.TKP, passed: session.score_tkp >= PASSING_GRADES.TKP }
                        ]

                        const failedSections = scores.filter(s => !s.passed)
                        const allPassed = failedSections.length === 0

                        // Determine Message
                        let title = "Rekomendasi Belajar"
                        let message: React.ReactNode = ""
                        let linkText = "Pelajari Materi"
                        if (allPassed) {
                            title = "Pertahankan Performamu!"
                            message = "Selamat! Kamu telah lulus passing grade di semua kategori. Pertahankan konsistensi latihanmu dan coba kerjakan soal-soal yang lebih sulit untuk memantapkan kesiapanmu."
                            linkText = "Lanjut Latihan Soal"
                        } else if (failedSections.length === 3) {
                            title = "Perlu Evaluasi Menyeluruh"
                            message = (
                                <>
                                    Hasil menunjukkan kamu belum memenuhi passing grade di semua kategori (<span className="font-bold text-foreground">TWK, TIU, TKP</span>). Disarankan untuk mempelajari kembali materi dasar secara sistematis dari awal.
                                </>
                            )
                            linkText = "Mulai dari Materi Dasar"
                        } else if (failedSections.length >= 1) {
                            // Build component array with separators
                            const comps = failedSections.map((s, idx) => {
                                const isLast = idx === failedSections.length - 1
                                const isSecondLast = idx === failedSections.length - 2
                                const suffix = isLast ? '' : isSecondLast ? ' dan ' : ', '
                                return <span key={s.type}><span className="font-bold text-foreground">{s.type}</span>{suffix}</span>
                            })

                            title = "Fokus Perbaikan Diperlukan"
                            message = (
                                <>
                                    Kamu masih belum memenuhi target di bidang: {comps}. Luangkan waktu lebih banyak untuk memperdalam materi kategori tersebut.
                                </>
                            )
                        }

                        return (
                            <div className={cn(
                                "border-2 rounded-2xl p-5 sm:p-8 flex flex-col sm:flex-row items-center sm:items-start gap-4 sm:gap-6 relative overflow-hidden shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]",
                                allPassed ? 'bg-green-50 border-green-600' : 'bg-[#fff740] border-gray-900'
                            )}>
                                <PaperBackground />
                                <div className={cn(
                                    "p-3 rounded-full shrink-0 relative z-10 border-2 shadow-sm",
                                    allPassed ? "bg-green-500 text-white border-green-700" : "bg-orange-500 text-white border-orange-700"
                                )}>
                                    {allPassed ? <CheckCircle2 size={24} className="sm:w-8 sm:h-8" /> : <AlertTriangle size={24} className="sm:w-8 sm:h-8" />}
                                </div>
                                <div className="relative z-10 text-center sm:text-left">
                                    <h3 className="font-black text-xl sm:text-2xl mb-1 sm:mb-2 text-gray-900">{title}</h3>
                                    <div className="text-gray-800 text-base sm:text-lg mb-4 sm:mb-6 leading-relaxed font-medium">
                                        {message}
                                    </div>
                                    {allPassed && (
                                        <Link href="/dashboard/latihan" className={cn(
                                            "inline-flex items-center gap-2 px-5 py-2 rounded-xl border-2 font-black transition-all shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] hover:translate-x-[1px] hover:translate-y-[1px] hover:shadow-none",
                                            allPassed ? "bg-green-600 text-white border-green-800" : "bg-gray-900 text-white border-black"
                                        )}>
                                            {linkText.replace('Materi', 'Latihan')} &rarr;
                                        </Link>
                                    )}
                                </div>
                                {allPassed && (
                                    <div className="absolute top-2 right-4 opacity-20 relative z-10">
                                        <Sparkles size={60} className="text-green-700" />
                                    </div>
                                )}
                            </div>
                        )
                    })()
                )}

                {/* 4. ACTION BAR (Sticky Bottom or Inline) */}
                <div className="flex flex-col sm:flex-row gap-4 sm:gap-6 justify-center pt-4 sm:pt-8 px-2 sm:px-0">
                    <Link
                        href="/dashboard/latihan"
                        className="flex justify-center items-center gap-2 sm:gap-3 px-6 sm:px-8 py-3 sm:py-4 rounded-2xl border-2 border-gray-900 bg-white hover:bg-gray-50 font-black text-lg sm:text-xl transition-all shadow-[3px_3px_0px_0px_rgba(0,0,0,1)] active:translate-x-[1px] active:translate-y-[1px] active:shadow-none"
                    >
                        <ArrowLeft size={20} className="sm:w-6 sm:h-6" /> Dashboard
                    </Link>

                    <RetakeButton isCombined={isCombined} singleType={singleType} />

                    <ScrollToReviewButton />
                </div>

                {/* 5. DETAILED ANSWER REVIEW (Existing Component) */}
                <div id="review-section" className="pt-8 border-t border-border">
                    <div className="flex items-center gap-3 mb-8">
                        <div className="h-10 w-2 bg-gray-900 rounded-full rotate-3"></div>
                        <h2 className="text-3xl font-black text-gray-900 uppercase tracking-widest">Pembahasan Lengkap</h2>
                    </div>

                    <ResultReviewClient answers={answers || []} />
                </div>

            </div>
        </ResultXPWrapper>
    )
}

import { createClient } from '@/utils/supabase/server'
import { redirect } from 'next/navigation'
import { signout } from '@/app/auth/actions'
import DashboardShell from '@/components/dashboard/DashboardShell'

export const dynamic = 'force-dynamic'
export const revalidate = 0

export default async function DashboardLayout({
    children,
}: {
    children: React.ReactNode
}) {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()

    if (!user) {
        redirect('/login')
    }

    // Fetch profile for status and details
    // We use maybeSingle() to avoid errors if profile doesn't exist yet
    let { data: profile } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .maybeSingle()

    // If profile doesn't exist, create it (new user or first time in dashboard)
    if (!profile) {
        const { data: newProfile, error: insertError } = await supabase
            .from('profiles')
            .insert({
                id: user.id,
                full_name: user.user_metadata?.full_name || (user as any).user_metadata?.name || null,
                tryout_quota: 0
            })
            .select()
            .single()

        if (!insertError) {
            profile = newProfile
        } else {
            console.error('[DashboardLayout] Failed to create profile:', insertError)
        }
    }

    const isAdminUser = profile?.role === 'admin'

    return (
        <DashboardShell user={user} profile={profile} signoutAction={signout} isAdmin={isAdminUser}>
            {children}
        </DashboardShell>
    )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { forgotPassword } from '@/app/auth/actions'
import { ArrowLeft, Loader2, Mail } from 'lucide-react'
import { toast } from 'sonner'
import PaperBackground from '@/components/PaperBackground'


export default function ForgotPasswordPage() {
    const [loading, setLoading] = useState(false)
    const [sent, setSent] = useState(false)

    const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault()
        setLoading(true)
        const formData = new FormData(event.currentTarget)

