                                <div className="absolute -top-4 left-1/2 -translate-x-1/2 w-40 h-10 bg-red-500 border-2 border-gray-900 shadow-sm flex items-center justify-center -rotate-2">
                                    <span className="text-white font-black uppercase tracking-widest text-sm">Peringatan Keras!</span>
                                </div>

                                <div className="flex flex-col items-center text-center mt-6 space-y-4">
                                    <div className="w-20 h-20 bg-red-100 border-2 border-gray-900 flex items-center justify-center rounded-full shadow-[4px_4px_0px_0px_rgba(220,38,38,0.2)]">
                                        <Trash2 size={40} className="text-red-600" />
                                    </div>

                                    <h3 className="text-3xl font-black text-gray-900">Hapus Akun?</h3>

                                    <div className="space-y-3 w-full">
                                        <p className="text-gray-600 font-bold italic leading-relaxed">
                                            "Tindakan ini tidak bisa dibatalkan."
                                        </p>
                                        <div className="bg-red-50 p-4 border-2 border-red-100 rounded-xl space-y-2">
                                            <p className="text-sm font-black text-red-800">Efek Penghapusan:</p>
                                            <ul className="text-xs text-red-700 font-bold space-y-1 text-left list-disc pl-4">
                                                <li>Semua riwayat ujian akan hilang</li>
                                                <li>Sisa kuota tryout akan hangus</li>
                                                <li>Data profil akan dihapus permanen</li>
                                                <li>Akses login akan dicabut selamanya</li>
                                            </ul>
                                        </div>

                                        <div className="pt-2">
                                            <label className="text-[10px] font-black uppercase text-gray-400 mb-1 block text-left">
                                                Ketik <span className="text-red-600">HAPUS</span> untuk konfirmasi
                                            </label>
                                            <input
                                                type="text"
                                                value={deleteConfirmText}
                                                onChange={(e) => setDeleteConfirmText(e.target.value.toUpperCase())}
                                                className="w-full px-4 py-3 border-2 border-gray-900 bg-white shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] text-center font-black text-xl tracking-widest outline-none focus:bg-red-50 focus:border-red-600 transition-colors"
                                                placeholder="Ketik di sini..."
                                                disabled={isDeleting}
                                            />
                                        </div>
                                    </div>

                                    <div className="flex flex-col w-full gap-3 pt-4">
                                        <button
                                            onClick={async () => {
                                                if (deleteConfirmText !== 'HAPUS') return
                                                setIsDeleting(true)
                                                try {
                                                    const res = await deleteAccount()
                                                    if (res.success) {
                                                        toast.success('Akun berhasil dihapus. Sampai jumpa!')
                                                        setTimeout(() => {
                                                            window.location.href = '/login'
                                                        }, 2000)
                                                    } else {
                                                        toast.error(res.error || 'Gagal menghapus akun')
                                                        setIsDeleting(false)
                                                    }
                                                } catch (err) {
                                                    toast.error('Terjadi kesalahan sistem')
                                                    setIsDeleting(false)
                                                }
                                            }}
                                            disabled={isDeleting || deleteConfirmText !== 'HAPUS'}
                                            className="w-full py-4 bg-red-600 text-white font-black text-xl border-2 border-gray-900 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] hover:translate-x-[3px] hover:translate-y-[3px] hover:shadow-none transition-all flex items-center justify-center gap-3 disabled:opacity-50 disabled:grayscale disabled:cursor-not-allowed"
                                        >
                                            {isDeleting ? <Loader2 className="animate-spin" /> : <Shield size={22} />}
                                            Ya, Hapus Permanen
                                        </button>
                                        <button
                                            onClick={() => {
                                                setShowDeleteModal(false)
                                                setDeleteConfirmText('')
                                            }}
                                            disabled={isDeleting}
                                            className="w-full py-3 bg-white text-gray-700 font-bold border-2 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] hover:bg-gray-50 transition disabled:opacity-50"
                                        >
                                            Batalkan
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )
                }
            </PageAnimateContainer >
        </div>
    )
}

'use client'

import React, { useEffect, useState } from 'react'
import {
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    Cell,
    ResponsiveContainer,
} from 'recharts'
import { BarChart3 } from 'lucide-react'

interface CategoryData {
    subject: string
    score: number
    fullMark: number
    passing: number
}

export default function CategoryChart({ data }: { data: CategoryData[] }) {
    const [mounted, setMounted] = useState(false)

    useEffect(() => {
        setMounted(true)
    }, []) // eslint-disable-line react-hooks/exhaustive-deps

    const getBarColor = (score: number, passing: number) => {
        if (score >= passing) return '#22c55e' // Green
        if (score >= passing * 0.8) return '#eab308' // Yellow
        return '#ef4444' // Red
    }

    if (!mounted) {
        return <div className="h-[400px] flex items-center justify-center border-2 border-dashed border-gray-300 bg-gray-50 text-gray-500">Memuat...</div>
    }

    if (!data || data.length === 0) {
        return <div className="h-[400px] flex items-center justify-center border-2 border-dashed border-gray-300 bg-gray-50 text-gray-500">Data tidak tersedia</div>
    }

    return (
        <div className="flex flex-col h-full min-h-[400px] p-2">
            <div className="mb-6 flex items-center gap-2">
                <div className="p-2 bg-yellow-100 border-2 border-gray-900 shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]">
                    <BarChart3 className="w-5 h-5 text-gray-900" />
                </div>
                <div>
                    <h3 className="text-xl font-bold text-gray-900">Analisis Kategori</h3>
                    <p className="text-sm text-gray-600">Skor Rata-rata</p>
                </div>
            </div>

            <div className="h-[250px] w-full py-4 bg-white border-2 border-gray-100 mb-6">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart
                        data={data}
                        margin={{ top: 10, right: 10, left: -20, bottom: 0 }}
                    >
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e5e7eb" />
                        <XAxis dataKey="subject" tick={{ fill: '#4b5563', fontWeight: 'bold' }} axisLine={false} tickLine={false} />
                        <YAxis tick={{ fill: '#9ca3af', fontSize: 10 }} axisLine={false} tickLine={false} />
                        <Tooltip />
                        <Bar dataKey="score" isAnimationActive={false}>
                            {data.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={getBarColor(entry.score, entry.passing)} />
                            ))}
                        </Bar>
                    </BarChart>
                </ResponsiveContainer>
            </div>

            <div className="grid grid-cols-3 gap-2 mt-auto">
                {data.map((d) => {
                    const gap = d.passing - d.score
                    const isPassed = d.score >= d.passing
                    return (
                        <div key={d.subject} className="text-center p-2 bg-gray-50 border-2 border-gray-900 shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] flex flex-col items-center justify-center min-h-[80px]">
                            <div className="text-sm font-black text-gray-400 uppercase tracking-widest mb-1">{d.subject}</div>
                            <div className="text-3xl font-black mb-1">{d.score}</div>
                            <div className={`text-xs font-bold ${isPassed ? 'text-green-600' : 'text-red-500'}`}>
                                {isPassed ? `Lulus (+${Math.abs(gap)})` : `Kurang ${gap}`}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
    )
}

'use client'

import {
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
    Area,
    AreaChart
} from 'recharts'
import { useState } from 'react'
import { TrendingUp, TrendingDown, Minus } from 'lucide-react'

interface TrendDataPoint {
    attempt: number
    date: string
    score: number
    fullDate: string
}

export default function TrendChart({
    data,
    trendDirection,
    trendPercentage,
    shortTermTrend,
    shortTermPercentage
}: {
    data: TrendDataPoint[],
    trendDirection: string,
    trendPercentage: number,
    shortTermTrend?: string,
    shortTermPercentage?: number
}) {
    const [viewMode, setViewMode] = useState<'long' | 'short'>('long')

    const currentDirection = viewMode === 'long' ? trendDirection : (shortTermTrend || trendDirection)
    const currentPercentage = viewMode === 'long' ? trendPercentage : (shortTermPercentage !== undefined ? shortTermPercentage : trendPercentage)

    const isUp = currentDirection === 'up'

    // Filter data for chart display if short term selected?
    // Actually, user might want to see the whole chart but see calculation for short term.
    // Or focus the chart too? Let's focus the chart too for clarity.

    const displayData = viewMode === 'short' ? data.slice(-10) : data

    return (
        <div className="flex flex-col h-full">
            <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center mb-6 gap-4">
                <div>
                    <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                        <TrendingUp className="w-6 h-6" /> Trend Nilai
                    </h3>
                    <p className="text-sm text-gray-600">
                        {viewMode === 'long' ? 'Progres skor total latihan' : 'Progres 10 latihan terakhir'}
                    </p>
                </div>

                <div className="flex items-center gap-3">
                    {/* View Selector - Notebook Style */}
                    <div className="flex bg-gray-100 border-2 border-gray-900 p-1">
                        <button
                            onClick={() => setViewMode('long')}
                            className={`px-3 py-1 text-sm font-bold transition-all ${viewMode === 'long'
                                ? 'bg-blue-300 text-gray-900 border-2 border-gray-900 shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]'
                                : 'text-gray-600 hover:text-gray-900'
                                }`}
                        >
                            Total
                        </button>
                        <button
                            onClick={() => setViewMode('short')}
                            className={`px-3 py-1 text-sm font-bold transition-all ${viewMode === 'short'
                                ? 'bg-blue-300 text-gray-900 border-2 border-gray-900 shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]'
                                : 'text-gray-600 hover:text-gray-900'
                                }`}
                        >
                            Terbaru
                        </button>
                    </div>

                    {/* Badge - Notebook Style */}
                    <div className={`px-3 py-1.5 text-sm font-bold flex items-center gap-1 border-2 border-gray-900 ${isUp
                        ? 'bg-green-300 text-green-800'
                        : currentDirection === 'down'
                            ? 'bg-red-300 text-red-800'
                            : 'bg-gray-200 text-gray-700'
                        }`}>
                        {isUp ? (
                            <><TrendingUp className="w-4 h-4" /> +{currentPercentage}%</>
                        ) : currentDirection === 'down' ? (
                            <><TrendingDown className="w-4 h-4" /> -{currentPercentage}%</>
                        ) : (
                            <><Minus className="w-4 h-4" /> 0%</>
                        )}
                    </div>
                </div>
            </div>

            <div className="h-[300px] w-full flex-1">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={displayData}>
                        <defs>
                            <linearGradient id="colorScore" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3} />
                                <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="hsl(var(--border))" opacity={0.5} />
                        <XAxis
                            dataKey="attempt"
                            stroke="hsl(var(--muted-foreground))"
                            fontSize={12}
                            tickLine={false}
                            axisLine={false}
                            tickFormatter={(value) => `#${value}`}
                        />
                        <YAxis
                            stroke="hsl(var(--muted-foreground))"
                            fontSize={12}
                            tickLine={false}
                            axisLine={false}
                            domain={[0, 'auto']}
                        />
                        <Tooltip
                            contentStyle={{
                                backgroundColor: '#fff',
                                borderRadius: '0',
                                border: '2px solid #1f2937',
                                boxShadow: '3px 3px 0px 0px rgba(0,0,0,1)'
                            }}
                            labelStyle={{ color: '#374151', marginBottom: '4px', fontWeight: 'bold' }}
                            itemStyle={{ color: '#1f2937', fontWeight: 'bold' }}
                            formatter={(value: any) => [`${value} Poin`, 'Skor Total']}
                            labelFormatter={(label) => `Latihan #${label}`}
                        />
                        <Area
                            type="monotone"
                            dataKey="score"
                            stroke="#3b82f6"
                            strokeWidth={3}
                            fillOpacity={1}
                            fill="url(#colorScore)"
                            animationDuration={1000}
                        />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>
    )
}

'use client'

import { useState, useCallback } from 'react'
import Cropper from 'react-easy-crop'
import { X, Check } from 'lucide-react'

// Define Area interface locally to avoid type issues
interface Area {
    width: number
    height: number
    x: number
    y: number
}

// --- Utility to create the cropped image blob ---
const createImage = (url: string): Promise<HTMLImageElement> =>
    new Promise((resolve, reject) => {
        const image = new Image()
        image.addEventListener('load', () => resolve(image))
        image.addEventListener('error', (error) => reject(error))
        image.setAttribute('crossOrigin', 'anonymous')
        image.src = url
    })

async function getCroppedImg(
    imageSrc: string,
    pixelCrop: Area
): Promise<Blob> {
    const image = await createImage(imageSrc)
    const canvas = document.createElement('canvas')
    const ctx = canvas.getContext('2d')

    if (!ctx) throw new Error('No 2d context')

    canvas.width = pixelCrop.width
    canvas.height = pixelCrop.height

    ctx.drawImage(
        image,
        pixelCrop.x,
        pixelCrop.y,
        pixelCrop.width,
        pixelCrop.height,
        0,
        0,
        pixelCrop.width,
        pixelCrop.height
    )

    return new Promise((resolve, reject) => {
        canvas.toBlob((blob) => {
            if (blob) resolve(blob)
            else reject(new Error('Canvas is empty'))
        }, 'image/jpeg')
    })
}

interface ImageCropperProps {
    imageSrc: string
    onCancel: () => void
    onCropComplete: (croppedBlob: Blob) => void
}

export default function ImageCropper({ imageSrc, onCancel, onCropComplete }: ImageCropperProps) {
    const [crop, setCrop] = useState({ x: 0, y: 0 })
    const [zoom, setZoom] = useState(1)
    const [croppedAreaPixels, setCroppedAreaPixels] = useState<Area | null>(null)
    const [isProcessing, setIsProcessing] = useState(false)

    const onCropCompleteHandler = useCallback((croppedArea: any, croppedAreaPixels: Area) => {
        setCroppedAreaPixels(croppedAreaPixels)
    }, [])

    const handleSave = async () => {
        if (!croppedAreaPixels) return

        setIsProcessing(true)
        try {
            const croppedBlob = await getCroppedImg(imageSrc, croppedAreaPixels)
            onCropComplete(croppedBlob)
        } catch (e) {
            console.error('Cropping error:', e)
        } finally {
            setIsProcessing(false)
        }
    }

    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/95 p-4">
            <div className="relative w-full max-w-xl bg-white border-4 border-gray-900 rounded-xl overflow-hidden shadow-[10px_10px_0px_0px_rgba(0,0,0,1)] flex flex-col h-[600px]">

                {/* Header */}
                <div className="p-4 bg-yellow-300 border-b-4 border-gray-900 flex justify-between items-center">
                    <h3 className="text-2xl font-black text-gray-900">SESUAIKAN FOTO</h3>
                    <button onClick={onCancel} className="p-1 border-2 border-gray-900 bg-white hover:bg-gray-100 rounded-lg">
                        <X size={24} />
                    </button>
                </div>

                {/* Cropper - Wrap in div with height */}
                <div className="flex-1 relative bg-gray-200">
                    <Cropper
                        image={imageSrc}
                        crop={crop}
                        zoom={zoom}
                        aspect={1}
                        onCropChange={setCrop}
                        onCropComplete={onCropCompleteHandler}
                        onZoomChange={setZoom}
                        cropShape="round"
                        showGrid={false}
                    />
                </div>

                {/* Controls */}
                <div className="p-6 bg-white border-t-4 border-gray-900 space-y-6">
                    <div className="flex items-center gap-4">
                        <span className="font-black text-gray-900">ZOOM</span>
                        <input
                            type="range"
                            value={zoom}
                            min={1}
                            max={3}
                            step={0.1}
                            onChange={(e) => setZoom(Number(e.target.value))}
                            className="w-full h-4 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-black border-2 border-gray-900"
                        />
                    </div>

                    <div className="flex gap-4">
                        <button
                            onClick={handleSave}
                            disabled={isProcessing}
                            className="flex-1 flex items-center justify-center gap-2 px-6 py-4 bg-blue-500 text-white font-black border-4 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] active:translate-x-[2px] active:translate-y-[2px] active:shadow-none transition-all disabled:opacity-50"
                        >
                            {isProcessing ? 'PROSES...' : 'SIMPAN FOTO'}
                        </button>
                        <button
                            onClick={onCancel}
                            disabled={isProcessing}
                            className="px-6 py-4 bg-white text-gray-900 font-black border-4 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] active:translate-x-[2px] active:translate-y-[2px] active:shadow-none transition-all"
                        >
                            BATAL
                        </button>
                    </div>
                </div>
            </div>
        </div>
    )
}
